node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Find user
const users = db.prepare(\"SELECT * FROM users WHERE name LIKE '%Maya%Chen%'\").all();
if (users.length === 0) { console.log('User not found'); process.exit(0); }
const user = users[0];
console.log('=== USER DETAILS ===');
console.log('User ID:', user.user_id);
console.log('Name:', user.name);
console.log('Email:', user.email);
console.log('Address:', user.address_json);

// Payment methods
const pms = db.prepare('SELECT * FROM rt_payment_methods WHERE user_id=?').all(user.user_id);
console.log('\n=== PAYMENT METHODS ===');
pms.forEach(pm => console.log(JSON.stringify(pm)));

// Orders
const orders = db.prepare(\"SELECT * FROM orders WHERE customer_id=? AND source_skill='tau2Retail'\").all(user.user_id);
console.log('\n=== ORDERS ===');
orders.forEach(o => {
    console.log('Order:', o.order_id, '| Status:', o.status, '| Address:', o.address_json);
    const items = db.prepare('SELECT * FROM order_items WHERE order_id=?').all(o.order_id);
    items.forEach(i => console.log('  Item:', i.item_id, '| Product:', i.product_id, '| Name:', i.name, '| Price:', i.unit_price, '| Options:', i.options));
    const payments = db.prepare('SELECT * FROM order_payments WHERE order_id=?').all(o.order_id);
    payments.forEach(p => console.log('  Payment:', p.transaction_type, p.amount, p.payment_method_id));
});
"

